const list = document.querySelector('#list'), search = document.querySelector('#search'), empty = document.querySelector('#empty'), dialog = document.querySelector('#article');
let filter = 'Todas';
const escapeHTML = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(){const q=search.value.trim().toLowerCase(); const items=machines.filter(m=>(filter==='Todas'||m.difficulty===filter)&&[m.name,m.platform,m.os,m.difficulty,...m.tags].join(' ').toLowerCase().includes(q)); document.querySelector('#count').textContent=String(machines.length).padStart(2,'0'); list.innerHTML=items.map(m=>`<button class="machine" data-name="${escapeHTML(m.name)}"><span class="machine-name"><span class="machine-icon">${m.os==='Windows'?'⊞':'◈'}</span><span><strong>${escapeHTML(m.name)}</strong><small>${escapeHTML(m.platform)} <span>·</span> ${escapeHTML(m.os)}</small></span></span><span class="difficulty ${m.difficulty==='Fácil'?'easy':m.difficulty==='Media'?'medium':'hard'}"><i></i>${escapeHTML(m.difficulty)}</span><span class="tags">${m.tags.map(t=>`<span>${escapeHTML(t)}</span>`).join('')}</span><span class="arrow">↗</span></button>`).join('');empty.hidden=items.length>0;}
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));render()}));search.addEventListener('input',render);document.addEventListener('keydown',e=>{if(e.key==='/'&&!dialog.open&&document.activeElement!==search){e.preventDefault();search.focus()}});
list.addEventListener('click',e=>{const button=e.target.closest('[data-name]');if(!button)return;const m=machines.find(x=>x.name===button.dataset.name);document.querySelector('#article-content').innerHTML=`<div class="article-intro"><div class="eyebrow"><span>✳</span> ${escapeHTML(m.platform)} / ${escapeHTML(m.os)}</div><h1>${escapeHTML(m.name)}<em>.</em></h1><p>${escapeHTML(m.intro)}</p><div class="article-meta"><span>${escapeHTML(m.difficulty)}</span>${m.tags.map(t=>`<span>${escapeHTML(t)}</span>`).join('')}</div></div><div class="article-layout"><aside><strong>EN ESTA ENTRADA</strong>${m.sections.map((s,i)=>`<a href="#section-${i}">${String(i+1).padStart(2,'0')} &nbsp; ${escapeHTML(s[0])}</a>`).join('')}</aside><div>${m.sections.map((s,i)=>`<section id="section-${i}" class="article-section"><span>0${i+1} /</span><h2>${escapeHTML(s[0])}</h2><p>${escapeHTML(s[1])}</p>${s[2]?`<pre><code>${escapeHTML(s[2])}</code></pre>`:''}</section>`).join('')}</div></div>`;dialog.showModal()});document.querySelector('#close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});render();
